var i=`code-smells-and-refactoring`;var n=89;var s={en:[{id:`T089-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Code Smells & Refactoring`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Property-based testing checks general invariants over many generated inputs rather than only hand-picked examples.`},{id:`B`,text:`BDD connects business examples to executable specifications through collaboration among developers, testers and domain stakeholders.`},{id:`C`,text:`Contract testing verifies assumptions between service providers and consumers, such as request shapes, response semantics and event schemas.`},{id:`D`,text:`Code smells are symptoms of possible design problems, not automatic proof that code is wrong.`}]},{id:`T089-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Code Smells & Refactoring`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Start from observable behavior and small testable increments, keeping tests independent of private implementation details.`},{id:`B`,text:`Typical mutants reverse comparisons, remove conditions or alter return values.`},{id:`C`,text:`Look for duplicated policy, long methods, feature envy, tangled dependencies and unclear names; identify the underlying change pressure.`},{id:`D`,text:`Record debt with business impact, risk, affected modules, approximate remediation cost and triggers.`}]},{id:`T089-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A 300-line booking controller may contain validation, pricing and persistence.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`Extract coherent policies and retain a thin orchestrator, confirming the same responses and side effects.`},{id:`B`,text:`Given a paid reservation inside the free-cancellation window, when the guest cancels, then refund eligibility is recorded and inventory becomes available according to policy.`},{id:`C`,text:`For a discount engine, first assert behavior at thresholds, empty carts and incompatible coupons; then implement rules and refactor duplicated conditions.`},{id:`D`,text:`Randomized concurrent sequences can expose missed invariants.`}]},{id:`T089-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Code Smells & Refactoring`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Static analysis has false positives and blind spots for runtime state and business logic.`},{id:`B`,text:`Shorter methods are not always clearer, and refactoring mixed with new features is hard to review.`},{id:`C`,text:`A large number of mocked unit tests may miss broken integration behavior.`},{id:`D`,text:`Feature files that repeat click-by-click UI steps become brittle.`}]},{id:`T089-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`Refactoring changes internal structure while preserving externally observable behavior.`}]}]},{id:`T089-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`Refactoring changes externally visible behavior to make code cleaner.`}]}]},{id:`T089-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Resist sweeping AI-generated rewrites with little test coverage.`}]}]},{id:`T089-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Code Smells & Refactoring`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Property-based testing is equivalent to generating arbitrary random inputs with no invariants.`},{id:`B`,text:`Code smells are symptoms of possible design problems, not automatic proof that code is wrong.`},{id:`C`,text:`Look for duplicated policy, long methods, feature envy, tangled dependencies and unclear names; identify the underlying change pressure.`},{id:`D`,text:`A long method is always a bug even if it has one clear responsibility.`}]},{id:`T089-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Code Smells & Refactoring`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Resist sweeping AI-generated rewrites with little test coverage.`},{id:`B`,text:`Extract coherent policies and retain a thin orchestrator, confirming the same responses and side effects.`},{id:`C`,text:`Refactoring changes externally visible behavior to make code cleaner.`},{id:`D`,text:`Mutations that survive tests always indicate a production bug.`}]},{id:`T089-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A 300-line booking controller may contain validation, pricing and persistence.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to identify three concrete code smells and propose a series of small diffs, each with preserved behavior and regression tests.`},{id:`B`,text:`Ask an agent to build a testing plan for a checkout workflow, map each requirement to the cheapest effective test layer and quantify expected runtime.`},{id:`C`,text:`Ask an agent to propose CI static checks for a modular backend, including forbidden dependencies, unsafe input flows and targeted suppressions.`},{id:`D`,text:`Ask an agent to turn ambiguous cancellation policy text into collaborative example tables, highlight unresolved business questions, then generate executable scenarios.`}]},{id:`T089-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`What observable improvement justifies a refactor apart from fewer lines?`}]}]},{id:`T089-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A 300-line booking controller may contain validation, pricing and persistence.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Code Smells & Refactoring`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T089-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A 300-line booking controller may contain validation, pricing and persistence.`,b:!0},{t:` — propose three checks for `},{t:`Code Smells & Refactoring`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T089-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A 300-line booking controller may contain validation, pricing and persistence.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T089-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Code Smells & Refactoring`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A 300-line booking controller may contain validation, pricing and persistence.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T089-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Запахи коду та рефакторинг`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Property-based testing перевіряє загальні інваріанти на багатьох згенерованих входах, а не лише вручну обраних прикладах.`},{id:`B`,text:`BDD поєднує бізнес-приклади з виконуваними специфікаціями через співпрацю розробників, тестувальників і предметних експертів.`},{id:`C`,text:`Контрактне тестування перевіряє домовленості між провайдером і споживачем: форми запитів, семантику відповідей і схеми подій.`},{id:`D`,text:`Code smells — сигнали можливих проблем дизайну, а не доказ помилки.`}]},{id:`T089-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Запахи коду та рефакторинг`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Починайте зі спостережуваної поведінки та малих кроків, не прив’язуючи тести до внутрішніх деталей.`},{id:`B`,text:`Типові мутанти змінюють знак порівняння, прибирають умову або змінюють повернення.`},{id:`C`,text:`Шукайте дублювання правил, довгі методи, feature envy, заплутані залежності й нечіткі назви; визначайте справжню причину проблеми.`},{id:`D`,text:`Фіксуйте борг із бізнесовим впливом, ризиком, модулями, приблизною ціною виправлення й тригерами.`}]},{id:`T089-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Контролер бронювань на 300 рядків може містити валідацію, ціну й збереження.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Винесіть узгоджені правила та залиште тонкий оркестратор, перевіривши незмінність відповідей і побічних ефектів.`},{id:`B`,text:`За умови оплаченого бронювання в період безкоштовного скасування, коли гість скасовує його, право на повернення коштів фіксується, а номер стає доступним за правилами.`},{id:`C`,text:`Для рушія знижок спершу перевірте пороги, порожній кошик і несумісні купони; потім реалізуйте правила й відрефакторіть повтори умов.`},{id:`D`,text:`Випадкові конкурентні послідовності можуть показати приховані збої.`}]},{id:`T089-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Запахи коду та рефакторинг`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Статичний аналіз має false positives і не бачить усі runtime-стани та бізнес-правила.`},{id:`B`,text:`Коротші методи не завжди ясніші, а рефакторинг разом із новими фічами важко перевіряти.`},{id:`C`,text:`Велика кількість unit-тестів із mocks може пропустити поламані інтеграції.`},{id:`D`,text:`Feature-файли з кроками кожного кліку крихкі.`}]},{id:`T089-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Рефакторинг змінює внутрішню структуру зі збереженням зовнішньої поведінки.`}]}]},{id:`T089-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Рефакторинг змінює зовнішню поведінку заради чистішого коду.`}]}]},{id:`T089-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Уникайте масштабних AI-переписувань без надійних тестів.`}]}]},{id:`T089-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Запахи коду та рефакторинг`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Property-based testing — це просто випадкові дані без визначених інваріантів.`},{id:`B`,text:`Code smells — сигнали можливих проблем дизайну, а не доказ помилки.`},{id:`C`,text:`Шукайте дублювання правил, довгі методи, feature envy, заплутані залежності й нечіткі назви; визначайте справжню причину проблеми.`},{id:`D`,text:`Довгий метод завжди є багом, навіть якщо має одну відповідальність.`}]},{id:`T089-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Запахи коду та рефакторинг`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Уникайте масштабних AI-переписувань без надійних тестів.`},{id:`B`,text:`Винесіть узгоджені правила та залиште тонкий оркестратор, перевіривши незмінність відповідей і побічних ефектів.`},{id:`C`,text:`Рефакторинг змінює зовнішню поведінку заради чистішого коду.`},{id:`D`,text:`Мутації, що вижили, завжди доводять продакшн-баг.`}]},{id:`T089-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Контролер бронювань на 300 рядків може містити валідацію, ціну й збереження.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента знайти три конкретні запахи й запропонувати серію малих diff зі збереженою поведінкою та регресійними тестами.`},{id:`B`,text:`Попросіть агента скласти план тестів checkout, зіставити вимоги з найдешевшим ефективним рівнем і оцінити час прогону.`},{id:`C`,text:`Попросіть агента запропонувати статичні перевірки CI для модульного бекенду: заборонені залежності, небезпечні потоки даних і точкові suppressions.`},{id:`D`,text:`Попросіть агента перетворити нечітку політику скасування на таблиці прикладів, виділити нез’ясовані бізнес-питання й створити виконувані сценарії.`}]},{id:`T089-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Яке спостережуване покращення виправдовує рефакторинг, окрім меншої кількості рядків?`}]}]},{id:`T089-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Контролер бронювань на 300 рядків може містити валідацію, ціну й збереження.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Запахи коду та рефакторинг`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T089-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Контролер бронювань на 300 рядків може містити валідацію, ціну й збереження.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Запахи коду та рефакторинг`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T089-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Контролер бронювань на 300 рядків може містити валідацію, ціну й збереження.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T089-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Запахи коду та рефакторинг`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Контролер бронювань на 300 рядків може містити валідацію, ціну й збереження.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var o={slug:i,topicId:89,questions:s};export{o as default,s as questions,i as slug,n as topicId};